// Used by Excel upload in Reports
const apiPostJson = async (url, body) => {
  const r = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  const json = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(json?.error || json?.message || `Request failed: ${r.status}`);
  return json;
};


const API = (import.meta.env.VITE_API_URL || '/api').trim();
const API_BASES = Array.from(new Set([
  API,
  'http://127.0.0.1:3002/api',
  'http://localhost:3002/api',
  '/api',
].filter(Boolean)));

// Resolve a backend file URL correctly:
// - When VITE_API_URL is absolute (http://192.168.x.x:3001/api), origin = that host
// - When VITE_API_URL is relative (/api), the backend is proxied through Vite,
//   so window.location.origin IS the correct base (Vite proxies /api → backend)
const _apiAbsolute = /^https?:\/\//i.test(API);
const ORIGIN = _apiAbsolute
  ? API.replace(/\/api\/?$/, '')    // strip /api suffix from absolute URL
  : window.location.origin;         // use current page origin (proxied via Vite)

const resolveDocUrl = url => {
  if (!url) return url;
  // Already absolute or blob/data → return as-is
  if (/^(https?:)?\/\//i.test(url) || url.startsWith('blob:') || url.startsWith('data:')) return url;
  // Relative path (e.g. /uploads/abc.pdf) → prefix with backend origin
  return `${ORIGIN}${url.startsWith('/') ? '' : '/'}${url}`;
};

