const fmtDate = v => { const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})$/); return m ? `${m[3]}/${m[2]}/${m[1]}` : String(v); };

// Repairs the classic "double-encoding" corruption: original UTF-8 bytes for
// Sinhala text got misread as Windows-1252/Latin-1 upstream (DB/API/CSV import)
// and re-saved that way, producing garbled strings like "‹¯° ½Ô°±œÚ‑" instead
// of Sinhala script. This reverses that specific corruption by re-mapping each
// character back to its original byte (covering both plain Latin-1 bytes and
// the Windows-1252-specific characters in the 0x80–0x9F range) and re-decoding
// as UTF-8 — but only keeps the result if it actually produces valid Sinhala
// characters, so already-correct text (English, proper Sinhala, etc.) is left
// untouched.

const fv = (row, key) => {
  if (!row) return '—';
  let val = row[key];
  if (key === 'name' && val == null) val = row.management_corporation_name;
  if (DATE_KEYS.includes(key) && val) return fmtDate(val);
  if (val == null) return '—';
  // Arrays and objects used to render as "[object Object]" or raw comma-joined
  // values in the printed/PDF table — flatten them into readable text instead.
  if (Array.isArray(val)) {
    if (!val.length) return '—';
    return val
      .map(v => fixMojibake((v && typeof v === 'object') ? (v.name ?? v.label ?? v.title ?? JSON.stringify(v)) : String(v)))
      .join(', ');
  }
  if (typeof val === 'object') {
    val = val.name ?? val.label ?? val.title ?? val.value ?? JSON.stringify(val);
  }
  val = fixMojibake(String(val));
  return val.trim() === '' ? '—' : val;
};
const statusColor = v => {
  if (!v || v === '—') return 'var(--text3)';
  const s = v.toLowerCase();
  if (s === 'active' || s === 'open' || s === 'new') return '#16a34a';
  if (s.includes('non active') || s === 'closed' || s === 'close') return '#dc2626';
  if (s === 'pending' || s.includes('review')) return '#d97706';
  return '#2563eb';
};
const apiFetch = async url => {
  const candidates = Array.from(new Set([
    url,
    ...API_BASES.map(base => {
      if (!url) return base;
      if (/^https?:\/\//i.test(url)) return url;
      if (/^https?:\/\//i.test(base)) {
        return `${base.replace(/\/$/, '')}${url.startsWith('/') ? url : `/${url}`}`;
      }
      return `${base.replace(/\/$/, '')}${url.startsWith('/') ? url : `/${url}`}`;
    }),
  ].filter(Boolean)));

  for (const candidate of candidates) {
    const r = await fetch(candidate, { cache: 'no-store' }).catch(() => null);
    if (r?.ok) {
      try { return await r.json(); } catch { return null; }
    }
  }
  return null;
};
const cnt = (arr, ...ss) => arr.filter(r => ss.includes(r.status)).length;

